import type { QuestionSeed } from "./gradedAssessment";
import { primaryEnglishDomains, primaryEnglishSelectionGroup, type PrimaryEnglishGrade, type PrimaryEnglishTrack } from "./primaryEnglishFramework";

type RawQuestion = readonly [label: string, question: string, hint: string, options: readonly string[], correct: number];

function groupedBank(grade: PrimaryEnglishGrade, track: PrimaryEnglishTrack, groups: readonly (readonly RawQuestion[])[]): QuestionSeed[] {
  const domains = primaryEnglishDomains(grade, track);
  return groups.flatMap((items, domainIndex) => items.map(([label, question, hint, options, correct]) => ({
    selectionGroup: primaryEnglishSelectionGroup(grade, track, domainIndex),
    topic: domains[domainIndex]!.label,
    label,
    question,
    hint,
    options: [...options],
    correct,
  })));
}

